// Okuma zinciri hata verdiyse: dosya gerçekten YOKSA boş listeyle devam edilir,
// ama dosya bozuk/erişilemez ise çalışma durdurulur — aksi hâlde liste boş
// sanılıp üzerine yazılır ve veriler kaybolur.
const _dosyaKontrol = (okuNode, cikarNode, dosya) => {
  const okuHata = $(okuNode).first().json.error;
  const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
  if (/ENOENT|no such file|not found/i.test(okuMesaj)) return; // dosya henüz oluşmamış
  const cikarHata = $(cikarNode).first().json.error;
  if (okuHata || cikarHata) {
    const m = okuMesaj || String((cikarHata && cikarHata.message) || cikarHata);
    throw new Error(dosya + ' okunamadı; okunmuş haber listesi korunsun diye durduruldu → ' + m);
  }
};
_dosyaKontrol('Kaynakları Oku', 'Kaynakları Çıkar', 'rss-kaynaklar.json');
_dosyaKontrol('Durumu Oku', 'Durumu Çıkar', 'rss-durum.json');


// Takip listesindeki her besleme için bir çıktı üretir (HTTP düğümü her biri
// için bir kez çalışır).
const j = $('Kaynakları Çıkar').first().json || {};
const d = (j.data && j.data.kaynaklar) || [];
const kaynaklar = (Array.isArray(d) ? d : [])
  .filter((k) => k && typeof k.url === 'string' && /^https?:\/\//i.test(k.url))
  .map((k) => ({ ad: String(k.ad || k.url), url: k.url }));

if (kaynaklar.length === 0) {
  throw new Error('rss-kaynaklar.json içinde geçerli kaynak yok. Örnek için local-files/rss-kaynaklar.ornek.json dosyasına bakın.');
}
return kaynaklar.map((k) => ({ json: k }));

// Tüm beslemeleri ayrıştırır, daha önce görülmemiş haberleri seçer.
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const cozumle = (s) => String(s || '')
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ').trim();

const alan = (blok, etiket) => {
  const m = blok.match(new RegExp('<' + etiket + '[^>]*>([\\s\\S]*?)</' + etiket + '>', 'i'));
  return m ? cozumle(m[1]) : '';
};
const linkBul = (blok) => {
  const rss = blok.match(/<link[^>]*>([\s\S]*?)<\/link>/i);
  if (rss && cozumle(rss[1])) return cozumle(rss[1]);
  const atom = blok.match(/<link[^>]+href=["']([^"']+)["']/i); // Atom beslemeleri
  return atom ? atom[1] : '';
};

const kaynaklar = $('Kaynakları Listele').all().map((x) => x.json);
const yanitlar = $input.all();

const durumJson = $('Durumu Çıkar').first().json || {};
const oncekiler = (durumJson.data && durumJson.data.gorulen) || [];
const gorulen = new Set(Array.isArray(oncekiler) ? oncekiler : []);
const ilkCalisma = gorulen.size === 0;

const yeniler = [];
const hatalar = [];

yanitlar.forEach((y, i) => {
  const kaynak = kaynaklar[i] || { ad: 'Bilinmeyen kaynak' }; // sıra korunur
  const json = y.json || {};
  if (json.error) {
    hatalar.push(kaynak.ad + ': ' + String(json.error.message || json.error).slice(0, 120));
    return;
  }
  const xml = String(json.data || '');
  const bloklar = (xml.match(/<item[\s\S]*?<\/item>/gi) || [])
    .concat(xml.match(/<entry[\s\S]*?<\/entry>/gi) || []);
  if (bloklar.length === 0) {
    hatalar.push(kaynak.ad + ': besleme okunamadı (RSS/Atom değil?)');
    return;
  }
  for (const b of bloklar.slice(0, 30)) {
    const link = linkBul(b);
    const baslik = alan(b, 'title');
    if (!link || !baslik || gorulen.has(link)) continue;
    gorulen.add(link);
    yeniler.push({
      kaynak: kaynak.ad,
      baslik: baslik.slice(0, 200),
      link,
      ozet: (alan(b, 'description') || alan(b, 'summary')).slice(0, 300),
      tarih: alan(b, 'pubDate') || alan(b, 'updated') || '',
    });
  }
});

// Liste sınırsız büyümesin: son 1000 bağlantı yeter.
const gorulenListe = [...gorulen].slice(-1000);

// İlk çalıştırmada arşivin tamamı "yeni" sayılır — bunu göndermek yerine
// sadece işaretleyip sonraki turdan itibaren haber veririz.
if (ilkCalisma) {
  return [{ json: {
    gonderilecek: false, yazilsin: true, gorulen: gorulenListe, yeniler: [],
    text: '', html: '', konu: '',
    bilgi: 'İlk çalıştırma: ' + gorulenListe.length + ' mevcut haber işaretlendi, bundan sonrakiler bildirilecek.',
  } }];
}

if (yeniler.length === 0) {
  return [{ json: {
    gonderilecek: false, yazilsin: true, gorulen: gorulenListe, yeniler: [],
    text: '', html: '', konu: '', bilgi: 'Yeni haber yok.' + (hatalar.length ? ' Sorunlu kaynak: ' + hatalar.join(' | ') : ''),
  } }];
}

const gun = new Date().toLocaleDateString('tr-TR', { day: 'numeric', month: 'long' });
const gruplar = new Map();
for (const h of yeniler) {
  if (!gruplar.has(h.kaynak)) gruplar.set(h.kaynak, []);
  gruplar.get(h.kaynak).push(h);
}

const satirlar = ['📰 Yeni haberler — ' + gun + ' (' + yeniler.length + ')'];
const htmlParca = [];
for (const [kaynak, liste] of gruplar) {
  satirlar.push('', '— ' + kaynak);
  htmlParca.push('<h3>' + esc(kaynak) + '</h3><ul>');
  for (const h of liste.slice(0, 10)) {
    satirlar.push('• ' + h.baslik + '\n  ' + h.link);
    htmlParca.push('<li><a href="' + esc(h.link) + '">' + esc(h.baslik) + '</a></li>');
  }
  if (liste.length > 10) satirlar.push('  … ve ' + (liste.length - 10) + ' tane daha');
  htmlParca.push('</ul>');
}
if (hatalar.length) satirlar.push('', '⚠️ ' + hatalar.join('\n⚠️ '));

// Modele gidecek başlık listesi (özet isteğe bağlı; Ollama kapalıysa atlanır).
const basliklar = yeniler.slice(0, 40)
  .map((h) => '- [' + h.kaynak + '] ' + h.baslik + (h.ozet ? ' — ' + h.ozet.slice(0, 160) : ''))
  .join('\n');

return [{ json: {
  gonderilecek: true, yazilsin: true, gorulen: gorulenListe, yeniler,
  konu: '📰 Yeni haberler — ' + gun + ' (' + yeniler.length + ')',
  text: satirlar.join('\n'),
  html: '<div style="font-family:system-ui,sans-serif;line-height:1.5"><h2>📰 Yeni haberler — ' +
        esc(gun) + '</h2>' + htmlParca.join('') +
        (hatalar.length ? '<p style="color:#b00">⚠️ ' + esc(hatalar.join(' | ')) + '</p>' : '') + '</div>',
  basliklar,
  model: String($env.OLLAMA_MODEL || 'qwen2.5:3b').trim(),
} }];

// Ollama özeti isteğe bağlıdır: RSS_AI_OZET=1 ise başlıklar modele gider.
const j = $input.first().json;
if (!j.gonderilecek) return [];
if (String($env.RSS_AI_OZET || '').trim() !== '1') return [];
return [{ json: j }];

// Model çalıştıysa özeti mesajın başına ekler; çalışmadıysa mesaj aynen kalır.
const hazirlik = $('Yeni Haberleri Bul').first().json || {};
const yanit = $input.first().json || {};
if (yanit.error || !yanit.response) {
  return [{ json: { ...hazirlik, aiNotu: '' } }];
}
const ozet = String(yanit.response).trim().slice(0, 1200);
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
return [{ json: {
  ...hazirlik,
  text: '🧠 Günün özeti:\n' + ozet + '\n\n' + hazirlik.text,
  html: '<div style="font-family:system-ui,sans-serif"><h3>🧠 Günün özeti</h3><p>' +
        esc(ozet).replace(/\n/g, '<br>') + '</p></div>' + hazirlik.html,
} }];

// AI özeti kapalıysa (ya da gönderilecek haber yoksa) metin olduğu gibi geçer.
const j = $input.first().json;
if (j.gonderilecek && String($env.RSS_AI_OZET || '').trim() === '1') return [];
return [{ json: j }];

// Telegram kuruluysa haberler oraya gider.
const j = $input.first().json;
if (!j.gonderilecek) return [];
const token = String($env.TELEGRAM_BOT_TOKEN || '').trim();
const chat = String($env.TELEGRAM_CHAT_ID || '').trim();
if (!token || !chat) return [];
return [{ json: { chat_id: chat, text: j.text.slice(0, 3900) } }];

// Telegram kurulu DEĞİLSE haberler mail olarak gider (çift bildirim olmasın).
const j = $input.first().json;
if (!j.gonderilecek) return [];
const kurulu = String($env.TELEGRAM_BOT_TOKEN || '').trim() && String($env.TELEGRAM_CHAT_ID || '').trim();
if (kurulu) return [];
return [{ json: { konu: j.konu, html: j.html } }];

// Dosyaya yalnızca görülen bağlantı listesi yazılır.
const j = $input.first().json;
if (!j.yazilsin) return [];
return [{ json: { gorulen: j.gorulen, sonCalisma: new Date().toISOString() } }];
